import numpy as np
from scipy import stats
from sklearn.feature_selection import f_classif

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers (clinical/stratum variables)
    drivers = []
    for i, (fid, ftype) in enumerate(zip(feats.ids, feats.types)):
        if ftype == 'clinical' or ftype == 'cohort':
            tstat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if abs(tstat) > 2.0:
                drivers.append(fid)

    # If no drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use first driver to adjust for confounding
    driver = drivers[0]
    driver_idx = feats.column(driver)

    # Select top features based on association with outcome
    f_scores, p_values = f_classif(feats.x, feats.y)
    top_features = [feats.ids[i] for i in range(len(feats.ids)) 
                    if p_values[i] < 0.05 and feats.ids[i] != driver]

    # Take top 3 features to keep model small
    top_features = top_features[:3]

    # Create products between top features
    products = []
    for i, a in enumerate(top_features):
        for b in top_features[i+1:]:
            products.append((a, b))

    # Return design with top features and their products
    return Design(
        drivers=tuple([driver] if drivers else ()),
        columns=tuple(top_features),
        products=tuple(products),
        loadings={fid: 1.0 for fid in top_features}
    )

